from app.network import configure_hub_http, current_revision
from huggingface_hub import HfApi, errors
seen = []
def handler(req):
    seen.append(req)
    if "missing" in str(req.url): return httpx2.Response(404, headers={"X-Error-Code": "RepoNotFound"}, json={"error": "nf"})
    if "down" in str(req.url): raise httpx2.ConnectError("boom", request=req)
    if "slow" in str(req.url): raise httpx2.ReadTimeout("slow", request=req)
